// Save all input data to file-based database
const inputData = $input.first().json;

console.log('=== SAVING ALL DATA TO DATABASE ===');
console.log('Input data keys:', Object.keys(inputData));
console.log('Full input data:', JSON.stringify(inputData, null, 2));

// Safe extraction with fallbacks - Enhanced company name detection
let companyName = 'Unknown Company';
let content = '';
let fileName = 'unknown_file.pdf';
let companyId = Date.now();
let primaryWebsite = '';
let primaryEmail = '';

try {
  // Multiple ways to extract company name - try all possible fields
  if (inputData.company_name) {
    companyName = inputData.company_name;
  } else if (inputData.company_info && inputData.company_info.company_name) {
    companyName = inputData.company_info.company_name;
  } else if (inputData.companyName) {
    companyName = inputData.companyName;
  } else if (inputData.name) {
    companyName = inputData.name;
  } else if (inputData.company) {
    companyName = inputData.company;
  }

  // Extract company information safely
  if (inputData.company_info) {
    primaryWebsite = inputData.company_info.primary_website || inputData.website || '';
    primaryEmail = inputData.company_info.primary_email || inputData.email || '';
  }

  // Extract content safely - try multiple possible fields
  if (inputData.content) {
    content = inputData.content;
  } else if (inputData.text) {
    content = inputData.text;
  } else if (inputData.extracted_text) {
    content = inputData.extracted_text;
  } else if (inputData.pdf_content) {
    content = inputData.pdf_content;
  }

  // Extract file name safely
  if (inputData.file_name) {
    fileName = inputData.file_name;
  } else if (inputData.fileName) {
    fileName = inputData.fileName;
  } else if (inputData.filename) {
    fileName = inputData.filename;
  }

  // Generate company ID
  companyId = inputData.company_id || inputData.id || Date.now();

} catch (error) {
  console.error('Error extracting data:', error.message);
  console.log('Using fallback values');
}

console.log('Extracted company name:', companyName);
console.log('Content length:', content.length);
console.log('File name:', fileName);
console.log('Company ID:', companyId);

// Validate content
if (!content || content.length < 50) {
  console.error('❌ CRITICAL: Insufficient content for analysis');
  content = 'No sufficient content available for analysis. Please ensure PDF extraction was successful.';
}

const savedData = {
  company_name: companyName,
  content: content,
  file_name: fileName,
  company_id: companyId,
  primary_website: primaryWebsite,
  primary_email: primaryEmail,
  saved_at: new Date().toISOString(),
  content_length: content.length
};

console.log('✅ Data saved successfully');
console.log('Final company name:', savedData.company_name);
console.log('Final content length:', savedData.content_length);
console.log('=== SAVE COMPLETE ===');

return { json: savedData };

