const checkerResponse = $input.first().json.response;
const formatOutputData = $node['Format Output'].json;

console.log(`Processing Checker response for company: ${formatOutputData.company_name}`);
console.log(`Format Output data:`, formatOutputData);

let checkerData;
try {
  const jsonMatch = checkerResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    checkerData = JSON.parse(jsonMatch[0]);
  } else {
    checkerData = {
      approved: true,
      feedback: "Content appears acceptable",
      score: 7
    };
  }
} catch (error) {
  console.log(`Checker JSON parsing failed: ${error.message}`);
  checkerData = {
    approved: true,
    feedback: "Content appears acceptable",
    score: 7
  };
}

console.log(`Checker result: ${checkerData.approved ? 'APPROVED' : 'REJECTED'} (Score: ${checkerData.score})`);

return {
  json: {
    ...formatOutputData,
    checker_approved: checkerData.approved,
    checker_feedback: checkerData.feedback,
    checker_score: checkerData.score
  }
};

const report = $input.first().json.response || '';
const ragData = $node['RAG Enhanced Prompt'].json;
const dbData = $node['Save ALL Data to Database'].json;

console.log(`Report received (Section 1): ${report.substring(0, 100)}...`);
console.log(`RAG enhanced company name: ${ragData.company_name}`);
console.log(`RAG documents found: ${ragData.rag_documents_found}`);
console.log(`Database data content length: ${dbData.content ? dbData.content.length : 'null'}`);

if (!report) {
  console.error('Report generation failed');
  return {
    json: {
      company_name: ragData.company_name || dbData.company_name,
      generated_content: 'Report generation failed',
      content: dbData.content,
      file_name: dbData.file_name,
      company_id: dbData.company_id,
      rag_enhanced: false
    }
  };
}

const cleanReport = report
  .replace(/\{\{[^}]*\}\}/g, '[removed-placeholder]')
  .replace(/\$json\.[\w.]+/g, '[removed-variable]')
  .replace(/\$node\[[^\]]+\]\.[\w.\[\]]+/g, '[removed-reference]')
  .replace(/\[date\]/gi, new Date().toLocaleDateString('en-US'))
  .replace(/\[company name\]/gi, ragData.company_name)
  .replace(/\[removed-placeholder\]\s*[,.]?\s*/g, '')  // Remove placeholder remnants
  .replace(/\[removed-variable\]\s*[,.]?\s*/g, '')   // Remove variable remnants
  .replace(/\[removed-reference\]\s*[,.]?\s*/g, '') // Remove reference remnants
  .replace(/\s+/g, ' ')  // Normalize spaces
  .trim();

// Validation - check for quality issues
const qualityIssues = [];
if (cleanReport.includes('{{') || cleanReport.includes('}}')) qualityIssues.push('template variables');
if (cleanReport.includes('$json') || cleanReport.includes('$node')) qualityIssues.push('code references');
if (cleanReport.includes('[company]') || cleanReport.includes('undefined')) qualityIssues.push('placeholders');
if (cleanReport.length < 200) qualityIssues.push('too short');
if (/^(.{1,50})\1+/.test(cleanReport)) qualityIssues.push('repetitive content');

if (qualityIssues.length > 0) {
  console.error(`❌ Report quality issues detected: ${qualityIssues.join(', ')}`);
  console.error('Report preview:', cleanReport.substring(0, 200));
}

console.log(`✅ RAG Enhanced Report Generated`);
console.log(`Cleaned Section 1 report: ${cleanReport.substring(0, 100)}...`);
console.log(`RAG documents used: ${ragData.rag_documents_found}`);
console.log(`Passing company name: ${ragData.company_name}`);

return {
  json: {
    company_name: ragData.company_name,
    generated_content: cleanReport,
    content: dbData.content,
    file_name: dbData.file_name,
    company_id: dbData.company_id,
    primary_website: dbData.primary_website,
    primary_email: dbData.primary_email,
    rag_enhanced: true,
    rag_documents_used: ragData.rag_documents_found,
    knowledge_context_length: ragData.knowledge_context ? ragData.knowledge_context.length : 0
  }
};

// Enhanced prompt with RAG knowledge integration
const companyData = $node['Save ALL Data to Database'].json;
const ragResults = $input.first().json;

console.log('=== RAG ENHANCED PROMPT GENERATION ===');
console.log('Company name:', companyData.company_name);
console.log('Document content length:', companyData.content ? companyData.content.length : 'null');
console.log('RAG results received:', !!ragResults);

// Extract RAG knowledge
let knowledgeContext = '';
if (ragResults && ragResults.documents && ragResults.documents.length > 0) {
  console.log('RAG documents found:', ragResults.documents.length);
  ragResults.documents.forEach((doc, index) => {
    if (doc.pageContent) {
      knowledgeContext += `Knowledge ${index + 1}: ${doc.pageContent}\n\n`;
    }
  });
  console.log('Knowledge context length:', knowledgeContext.length);
} else {
  console.log('No RAG documents found - proceeding with document content only');
  knowledgeContext = 'No specific knowledge base information available.';
}

// Create enhanced prompt with both document and knowledge base content
const enhancedPrompt = `You are a senior financial analyst creating a professional due diligence report. Generate a comprehensive "Introduction & Engagement Context" section for: ${companyData.company_name}

SOURCE DOCUMENT CONTENT:
${companyData.content}

KNOWLEDGE BASE CONTEXT:
${knowledgeContext}

REQUIREMENTS:
- Use BOTH the source document content AND knowledge base information
- Write in professional, business-appropriate language
- Minimum 400 words, well-structured paragraphs
- Include specific details about the company's business, operations, and market position
- Structure with clear subsections: Purpose, Scope, Business Context, Market Relevance, and Timeframe
- Reference specific data points, figures, or business details from BOTH sources
- Integrate knowledge base insights with document facts
- Avoid generic statements - be specific to this company
- Do not use placeholder text or template variables

Generate a detailed, professional analysis that combines document content with knowledge base insights.`;

console.log('Enhanced prompt length:', enhancedPrompt.length);
console.log('Enhanced prompt preview:', enhancedPrompt.substring(0, 500));
console.log('=== RAG ENHANCEMENT COMPLETE ===');

return {
  json: {
    enhanced_prompt: enhancedPrompt,
    company_name: companyData.company_name,
    content: companyData.content,
    knowledge_context: knowledgeContext,
    rag_documents_found: ragResults?.documents?.length || 0
  }
};
